#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=6
KEEPLORE_CONFIGURATION=/etc/voice-agent/keeplore.conf
KEEPLORE_TOOLS=/opt/voice-agent/keeplore
PRODUCTION_BROWSER_STATE=/var/lib/voice-agent/browser/keeplore-production.json
PROMOTION_JOURNAL=/var/lib/keeplore-promotions/attempts.jsonl
ACCEPTANCE_RECORD=/var/lib/voice-agent/acceptance/slice-three.json

if [[ ! -e /opt/voice-agent/current ]]; then
  warn "Run this wizard on the Agent Host after promoting the reviewed Voice Agent release."
  exit 1
fi
RELEASE_ROOT=
if ! RELEASE_ROOT=$(readlink -f /opt/voice-agent/current) || \
  [[ ! $RELEASE_ROOT =~ ^/opt/voice-agent/releases/[0-9a-f]{40}$ ]] || \
  [[ ! -d $RELEASE_ROOT ]]; then
  warn "The active Voice Agent release path is invalid."
  exit 1
fi
PLAYWRIGHT="$RELEASE_ROOT/node_modules/.bin/playwright"

banner "Keeplore Button Trial promotion and verification"

stage "Confirm the reviewed pull request is ready for Human Merge"
say "This wizard runs after the Delegation of issue #13 opened its pull request."
sudo test -f "$KEEPLORE_CONFIGURATION"
DELEGATION=$(sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/keeplore-delegation-inspect.ts")
PULL_REQUEST=$(jq -er '.delegation.result.pullRequest.url' <<<"$DELEGATION")
TRIAL_BRANCH=$(jq -er '.delegation.result.branch' <<<"$DELEGATION")
if [[ $(jq -r '.delegation.result.status' <<<"$DELEGATION") != completed ]]; then
  warn "The latest Delegation is not completed; finish the trial before promoting."
  exit 1
fi
note "Pull request: $PULL_REQUEST"
note "Delegated branch: $TRIAL_BRANCH"
sudo install -d -o voice-agent -g voice-agent -m 0750 \
  /var/lib/voice-agent/acceptance
if ! sudo test -f "$ACCEPTANCE_RECORD"; then
  sudo -u voice-agent /usr/bin/node --experimental-strip-types \
    "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" init \
    --campaign-id keeplore-button-trial --record "$ACCEPTANCE_RECORD"
  sudo -u voice-agent /usr/bin/node --experimental-strip-types \
    "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" record-publication \
    --branch "$TRIAL_BRANCH" --pull-request "$PULL_REQUEST" \
    --record "$ACCEPTANCE_RECORD" --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
fi

stage "Enroll the trusted production browser session"
say "Production appearance is measured by the promoter, never by the Subagent's browser."
note "This session is root-owned and separate from /var/lib/voice-codex/browser."
sudo install -d -o voice-agent -g voice-agent -m 0700 /var/lib/voice-agent/browser
sudo -u voice-agent env \
  HOME=/var/lib/voice-agent \
  PLAYWRIGHT_BROWSERS_PATH=/var/lib/voice-agent/.cache/ms-playwright \
  "$PLAYWRIGHT" install chromium
if [[ -z ${DISPLAY:-} ]]; then
  warn "No graphical display is forwarded. Reconnect with trusted X11 forwarding."
  exit 1
fi
step "Sign into Keeplore in the opened browser as the account the owner reviews with, then close it."
confirm "Open the Keeplore production verification browser now?" || exit 1
sudo -u voice-agent env \
  DISPLAY="$DISPLAY" \
  HOME=/var/lib/voice-agent \
  PLAYWRIGHT_BROWSERS_PATH=/var/lib/voice-agent/.cache/ms-playwright \
  "$PLAYWRIGHT" open --save-storage "$PRODUCTION_BROWSER_STATE" \
  https://keeplore.app
sudo test -s "$PRODUCTION_BROWSER_STATE"
sudo chown voice-agent:voice-agent "$PRODUCTION_BROWSER_STATE"
sudo chmod 0600 "$PRODUCTION_BROWSER_STATE"

stage "Activate the Deployment Contract revision that verifies appearance"
say "Ordinary Keeplore Promotions do not verify the matched controls; this trial's does."
note "Appearance verification stays off until this revision is activated, so the onboarding merge and every unrelated change promote unchanged."
if ! sudo grep -q '^KEEPLORE_APPEARANCE_VERIFICATION=1$' "$KEEPLORE_CONFIGURATION"; then
  confirm "Activate post-Promotion appearance verification for Keeplore?" || exit 1
  # Changing how a Human Merge is verified is a new Deployment Contract
  # revision, so the attempts built under it are distinguishable from every
  # attempt built before it.
  CONTRACT_REVISION=$(sudo sed -n 's/^KEEPLORE_CONTRACT_REVISION=//p' \
    "$KEEPLORE_CONFIGURATION" | tail -n1)
  [[ $CONTRACT_REVISION =~ ^[1-9][0-9]*$ ]] || CONTRACT_REVISION=1
  sudo sed -i '/^KEEPLORE_APPEARANCE_VERIFICATION=/d;/^KEEPLORE_CONTRACT_REVISION=/d' \
    "$KEEPLORE_CONFIGURATION"
  printf 'KEEPLORE_APPEARANCE_VERIFICATION=1\nKEEPLORE_CONTRACT_REVISION=%s\n' \
    "$((CONTRACT_REVISION + 1))" \
    | sudo tee -a "$KEEPLORE_CONFIGURATION" >/dev/null
fi
sudo grep -E '^KEEPLORE_(APPEARANCE_VERIFICATION|CONTRACT_REVISION|REQUIRED_CHECK)=' \
  "$KEEPLORE_CONFIGURATION"

stage "Human Merge the reviewed pull request"
say "Only an authenticated human merge authorizes Promotion of that exact commit."
note "The Administrative Publisher App cannot merge; pushing the branch or opening the pull request promotes nothing."
open_url "$PULL_REQUEST"
step "Review the branch, single commit, changed path, checks, and screenshots."
step "Merge it yourself with your own authenticated GitHub account."
note "Already merged? A Promotion cannot verify a merge already serving. Read"
note "\"The trial's own merge has already happened\" in"
note "docs/operations/keeplore-button-trial-promotion.md before continuing."
pause "Press Enter after the merge completes."
ask MERGE_COMMIT "40-character merge commit produced by the Human Merge"
if [[ ! $MERGE_COMMIT =~ ^[0-9a-f]{40}$ ]]; then
  warn "A 40-character merge commit is required."
  exit 1
fi
ask MERGE_ACTOR "Authenticated GitHub user who merged it"
sudo -u voice-agent /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" record-merge \
  --actor "$MERGE_ACTOR" --commit "$MERGE_COMMIT" \
  --merged-at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
  --record "$ACCEPTANCE_RECORD" --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%SZ)"

stage "Promote and verify the exact merge commit"
say "The Promotion builds an immutable Release outside the live checkout, preflights it, switches atomically, then verifies health and appearance."
note "A failed verification restores the retained Release; nothing here treats that as complete."
# A Promotion of the Release already serving is a no-op by design, so it
# captures no baseline and produces no verdict. Say so here rather than letting
# stage 6 report a mysteriously empty verification.
if [[ $(sudo readlink -f /opt/keeplore/current 2>/dev/null | xargs -r basename) \
  == "$MERGE_COMMIT" ]]; then
  warn "Keeplore already serves $MERGE_COMMIT, so this Promotion would verify nothing."
  warn "See \"The trial's own merge has already happened\" in"
  warn "docs/operations/keeplore-button-trial-promotion.md."
  exit 1
fi
PROMOTION_STATUS=0
sudo "$KEEPLORE_TOOLS/promote-keeplore-main.sh" "$MERGE_COMMIT" || PROMOTION_STATUS=$?
sudo tail -n 3 "$PROMOTION_JOURNAL" | jq -c '.'
if [[ $PROMOTION_STATUS -ne 0 ]]; then
  warn "The Promotion Attempt failed and the previous Release was restored."
  warn "Slice three is not accepted. Read the verdict above, fix the change, and start a new Delegation."
fi

stage "Resolve the Delegated Worktree, notify the owner, and accept slice three"
say "The trial ends in one Evidence Record linking the request, Delegation, merge, Release, verification, and notice."
TRIAL_TASK_ID=$(jq -er '.task.id' <<<"$DELEGATION")
EVIDENCE_URL="https://voice.stephens.page/?task=$TRIAL_TASK_ID"

# The pull-request state and the callback outcome are observed rather than
# typed: the resolver reads the state from GitHub and removes the worktree only
# when the policy allows it, and the notice sender reads what the Durable Task
# actually recorded about the Completion Callback.
WORKTREE=$(sudo "$KEEPLORE_TOOLS/resolve-keeplore-worktree.sh" "${PULL_REQUEST##*/}")
PULL_REQUEST_STATE=$(jq -r '.pullRequestState' <<<"$WORKTREE")
note "Worktree: $(jq -r '.reason' <<<"$WORKTREE")"

NOTICE=$(sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  KEEPLORE_TRIAL_TASK_ID="$TRIAL_TASK_ID" \
  RESEND_API_KEY="${RESEND_API_KEY:-}" \
  RESEND_DOMAIN_ID="${RESEND_DOMAIN_ID:-}" \
  /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/keeplore-trial-completion-notice.ts")
CALLBACK_OUTCOME=$(jq -r \
  'if .kind == "completion-callback" then "authorized" else (.reason | sub("^callback-"; "")) end' \
  <<<"$NOTICE")
note "Owner notice: $NOTICE"

EVIDENCE_STATUS=0
TRIAL_RECORD=$(sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  KEEPLORE_MERGE_COMMIT="$MERGE_COMMIT" \
  KEEPLORE_PULL_REQUEST_STATE="$PULL_REQUEST_STATE" \
  KEEPLORE_COMPLETION_CALLBACK="$CALLBACK_OUTCOME" \
  VOICE_AGENT_EVIDENCE_RECORD_URL="$EVIDENCE_URL" \
  /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/keeplore-trial-promotion-inspect.ts") \
  || EVIDENCE_STATUS=$?
printf '%s\n' "$TRIAL_RECORD"
open_url "$EVIDENCE_URL"
step "Confirm the authenticated Evidence Record shows the same conclusion."
if [[ $EVIDENCE_STATUS -ne 0 || $PROMOTION_STATUS -ne 0 ]]; then
  warn "Slice three remains unaccepted until a real production verification succeeds after a Human Merge."
  finish
  exit 1
fi
sudo -u voice-agent /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" record-verification \
  --appearance "$(jq -r '.trial.verification.appearance.outcome' <<<"$TRIAL_RECORD")" \
  --card-view "$(jq -r 'if .trial.verification.cardView.unchanged then "unchanged" else "regressed" end' <<<"$TRIAL_RECORD")" \
  --commit "$MERGE_COMMIT" \
  --desktop-screenshot "$(jq -r '[.trial.verification.screenshots[].viewport.name] | index("desktop") != null' <<<"$TRIAL_RECORD")" \
  --evidence-record "$EVIDENCE_URL" \
  --health "$(jq -r '.trial.verification.health.outcome' <<<"$TRIAL_RECORD")" \
  --mobile-screenshot "$(jq -r '[.trial.verification.screenshots[].viewport.name] | index("mobile") != null' <<<"$TRIAL_RECORD")" \
  --record "$ACCEPTANCE_RECORD" \
  --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
  --rollback "$(jq -r 'if .trial.rollback.performed then "performed" else "none" end' <<<"$TRIAL_RECORD")"
sudo -u voice-agent /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" status \
  --record "$ACCEPTANCE_RECORD"
confirm "Accept slice three on this verified production evidence?" || exit 1
sudo -u voice-agent /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/acceptance/src/slice-three-cli.ts" accept \
  --record "$ACCEPTANCE_RECORD" --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%SZ)"

finish
